with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , cast(null as varchar) as BILL_TYPE
        , cast(null as varchar) as BILL_DATE
        , cast(null as varchar) as BILL_STATUS_TYPE
        , cast(null as varchar) as BILLED_AMOUNT
        , cast(null as varchar) as APPROVED_AMOUNT
        , cast(null as varchar) as DISALLOWED_AMOUNT
        , cast(null as varchar) as DISALLOWANCE_REASON
        , cast(null as varchar) as AUTHORISED_AMOUNT
        , 'BJAZ_HM_BILL_CHARGE' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_charge') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , BILL_TYPE as BILL_TYPE
        , BILL_DATE as BILL_DATE
        , BILL_STATUS_TYPE as BILL_STATUS_TYPE
        , TOT_BILL_AMT as BILLED_AMOUNT
        , TOT_APPROVED_AMT as APPROVED_AMOUNT
        , TOT_DISALLOW_AMT as DISALLOWED_AMOUNT
        , DIS_APP_REASON as DISALLOWANCE_REASON
        , cast(null as varchar) as AUTHORISED_AMOUNT
        , 'BJAZ_HM_BILL_DETAIL' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_detail') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , BILL_TYPE as BILL_TYPE
        , BILL_DATE as BILL_DATE
        , BILL_STATUS_TYPE as BILL_STATUS_TYPE
        , TOT_BILL_AMT as BILLED_AMOUNT
        , TOT_APPROVED_AMT as APPROVED_AMOUNT
        , TOT_DISALLOW_AMT as DISALLOWED_AMOUNT
        , DIS_APP_REASON as DISALLOWANCE_REASON
        , TOT_APP_AMTMOU as AUTHORISED_AMOUNT
        , 'BJAZ_HM_BILL_DETAIL_OCR' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_detail_ocr') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK
        , cast(null as varchar) as BILL_TYPE
        , cast(null as varchar) as BILL_DATE
        , cast(null as varchar) as BILL_STATUS_TYPE
        , cast(null as varchar) as BILLED_AMOUNT
        , cast(null as varchar) as APPROVED_AMOUNT
        , cast(null as varchar) as DISALLOWED_AMOUNT
        , cast(null as varchar) as DISALLOWANCE_REASON
        , cast(null as varchar) as AUTHORISED_AMOUNT
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(CLID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , cast(null as varchar) as BILL_TYPE
        , cast(null as varchar) as BILL_DATE
        , cast(null as varchar) as BILL_STATUS_TYPE
        , cast(null as varchar) as BILLED_AMOUNT
        , TOT_APPROVED_AMT as APPROVED_AMOUNT
        , TOT_DISALLOW_AMT as DISALLOWED_AMOUNT
        , cast(null as varchar) as DISALLOWANCE_REASON
        , cast(null as varchar) as AUTHORISED_AMOUNT
        , 'BJAZ_HM_PRO_ASSESSMENT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_pro_assessment') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , cast(null as varchar) as BILL_TYPE
        , cast(null as varchar) as BILL_DATE
        , cast(null as varchar) as BILL_STATUS_TYPE
        , TOTAL_BILL_AMT as BILLED_AMOUNT
        , TOTAL_APPROVED_AMT as APPROVED_AMOUNT
        , TOTAL_DISALLOW_AMT as DISALLOWED_AMOUNT
        , cast(null as varchar) as DISALLOWANCE_REASON
        , cast(null as varchar) as AUTHORISED_AMOUNT
        , 'BJAZ_HM_GPA_BILL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_gpa_bill_dtls') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__DISC_CASE_ID))) as HUB_CLAIM_HK
        , cast(null as varchar) as BILL_TYPE
        , DISC_BILL_DATE as BILL_DATE
        , cast(null as varchar) as BILL_STATUS_TYPE
        , cast(null as varchar) as BILLED_AMOUNT
        , cast(null as varchar) as APPROVED_AMOUNT
        , cast(null as varchar) as DISALLOWED_AMOUNT
        , cast(null as varchar) as DISALLOWANCE_REASON
        , cast(null as varchar) as AUTHORISED_AMOUNT
        , 'BJAZ_HAT_DISC_SUMMARY_LST' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_disc_summary_lst') }}
    where (nullif(trim(DISC_CASE_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CASE_ID))) as HUB_CLAIM_HK
        , cast(null as varchar) as BILL_TYPE
        , BILL_DATE as BILL_DATE
        , cast(null as varchar) as BILL_STATUS_TYPE
        , cast(null as varchar) as BILLED_AMOUNT
        , cast(null as varchar) as APPROVED_AMOUNT
        , cast(null as varchar) as DISALLOWED_AMOUNT
        , cast(null as varchar) as DISALLOWANCE_REASON
        , cast(null as varchar) as AUTHORISED_AMOUNT
        , 'BJAZ_HAT_OCR_FINA_PERTICULARS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_ocr_fina_perticulars') }}
    where (nullif(trim(CASE_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BILL_TYPE end) as BILL_TYPE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then BILL_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BILL_DATE end)) as BILL_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BILL_STATUS_TYPE end) as BILL_STATUS_TYPE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then BILLED_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BILLED_AMOUNT end)) as BILLED_AMOUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then APPROVED_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then APPROVED_AMOUNT end)) as APPROVED_AMOUNT,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then DISALLOWED_AMOUNT end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISALLOWED_AMOUNT end)) as DISALLOWED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISALLOWANCE_REASON end) as DISALLOWANCE_REASON,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AUTHORISED_AMOUNT end) as AUTHORISED_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when BILL_TYPE is not null or BILL_DATE is not null or BILL_STATUS_TYPE is not null or BILLED_AMOUNT is not null or APPROVED_AMOUNT is not null or DISALLOWED_AMOUNT is not null or DISALLOWANCE_REASON is not null or AUTHORISED_AMOUNT is not null
                     then md5(upper(coalesce(cast(BILL_TYPE as varchar), '') || '|' || coalesce(cast(BILL_DATE as varchar), '') || '|' || coalesce(cast(BILL_STATUS_TYPE as varchar), '') || '|' || coalesce(cast(BILLED_AMOUNT as varchar), '') || '|' || coalesce(cast(APPROVED_AMOUNT as varchar), '') || '|' || coalesce(cast(DISALLOWED_AMOUNT as varchar), '') || '|' || coalesce(cast(DISALLOWANCE_REASON as varchar), '') || '|' || coalesce(cast(AUTHORISED_AMOUNT as varchar), '')))
                end as SAT_CLAIM_PROVIDER_BILLING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_PROVIDER_BILLING_HASHDIFF is not null
